/* Administration of commercial rules. Personal health data is never loaded. */
window.NeoShopPromotions=(()=>{
 const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>window.NeoShopCore.money(v);
 let owner='',revision=0,ctx={},data=null,draft=null,section='automatic',busy=false,error='',redraw=()=>{};
 const rpc=(action,payload={})=>window.NeoCloud.shop(action,payload);
 const input=(name,label,value='',extra='')=>`<label>${label}<input name="${name}" value="${e(value)}" ${extra}></label>`;
 const checked=v=>v?'checked':'';
 function session(user){const key=user?.id||'';if(key===owner)return;owner=key;revision++;data=null;draft=null;busy=false;error='';ctx={};redraw=()=>{};}
 async function open(context,draw,tab='automatic'){ctx=context;redraw=draw;section=tab;draft=null;data=null;error='';const token=revision;busy=true;try{const result=await rpc('promotions');if(token===revision)data=result;}catch(err){if(token===revision)error=err.message;}finally{if(token===revision){busy=false;redraw();}}}
 const localTime=value=>{if(!value)return '';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
 function editor(){const r=draft,coupon=section==='coupons';return `<section class="card space"><h2>${r.id?'Editar':'Criar'} ${coupon?'cupom':'promoção automática'}</h2><form data-promo-form="rule" class="space">${input('name','Nome da regra',r.name||'','required minlength="2" maxlength="100"')}${coupon?input('code','Código do cupom',r.code||'','required minlength="3" maxlength="32" pattern="[A-Za-z0-9_-]{3,32}" autocomplete="off" autocapitalize="characters"'):''}<div class="form-grid"><label>Tipo de benefício<select name="kind">${[['percent','Desconto em %'],['fixed','Desconto em R$'],...(coupon?[['tracking','Somente identificar a origem']]:[])].map(([v,t])=>`<option value="${v}" ${r.kind===v?'selected':''}>${t}</option>`).join('')}</select></label>${input('amount','Valor (% ou R$; origem: 0)',r.kind==='percent'?r.value/100:r.kind==='fixed'?r.value/100:0,'required inputmode="decimal"')}</div><fieldset class="shop-rule-products space"><legend>Produtos participantes</legend><p class="sub">Sem seleção = todos. Quantidade e valor mínimo contam somente os produtos participantes. Ofertas automáticas válidas para uma unidade e qualquer pagamento ganham selo e preço reduzido na loja; regras condicionais são calculadas no carrinho.</p><div>${ctx.products.map(p=>`<label class="shop-accept"><input type="checkbox" name="product_ids" value="${e(p.id)}" ${checked(r.product_ids?.includes(p.id))}> ${e(p.name)}</label>`).join('')}</div></fieldset><div class="form-grid space">${input('min_quantity','Quantidade mínima (unidades somadas)',r.min_quantity??1,'type="number" required min="1" max="600" step="1"')}${input('minimum','Valor mínimo em produtos (R$)',(r.min_subtotal_cents||0)/100,'required inputmode="decimal"')}<label>Forma de pagamento<select name="payment_method">${[['any','Qualquer forma'],['pix','Pix'],['credit_card','Cartão de crédito'],['boleto','Boleto']].map(([v,t])=>`<option value="${v}" ${r.payment_method===v?'selected':''}>${t}</option>`).join('')}</select></label>${input('maximum','Desconto máximo em R$ (opcional)',r.max_discount_cents?r.max_discount_cents/100:'','inputmode="decimal"')}${input('starts_at','Início (horário deste aparelho)',localTime(r.starts_at),'type="datetime-local"')}${input('ends_at','Fim (horário deste aparelho)',localTime(r.ends_at),'type="datetime-local"')}${input('max_uses','Limite total de usos (opcional)',r.max_uses||'','type="number" min="1" max="1000000" step="1"')}${input('per_user_limit','Usos por cliente (opcional)',r.per_user_limit||'','type="number" min="1" max="1000000" step="1"')}</div>${coupon?`<fieldset class="space"><legend>Origem e associação</legend>${input('source','Campanha ou canal (opcional)',r.source||'','maxlength="100" placeholder="Ex.: Instagram · campanha de novembro"')}${input('referrer_email','E-mail do usuário que indicou (opcional)',r.referrer_email||'','type="email" maxlength="254"')}<p class="sub">Registra a indicação nos pedidos. Não gera comissão automaticamente.</p>${input('restricted_email','Exclusivo para este cliente (opcional)',r.restricted_email||'','type="email" maxlength="254"')}<p class="sub">Em branco, qualquer cliente que cumpra as condições poderá usar.</p></fieldset>`:''}<label class="shop-accept"><input name="stackable" type="checkbox" ${checked(r.stackable)}> Permitir acumular com outras regras que também permitam</label><label class="shop-accept"><input name="active" type="checkbox" ${checked(r.active)}> Regra ativa</label><p class="sub">As condições se somam. O frete não recebe desconto. O total dos produtos permanece em pelo menos R$ 0,01.</p><div class="shop-admin-actions space"><button class="primary" ${busy?'disabled':''}>Salvar ${coupon?'cupom':'promoção'}</button><button class="secondary" type="button" data-promo="cancel">Cancelar</button></div></form></section>`;}
 function view(){if(!ctx.admin)return '<p>Acesso restrito à administração.</p>';const rows=(data?.rules||[]).filter(r=>section==='coupons'?!!r.code:!r.code);return `<div class="shop-admin-head"><h2>Promoções e cupons</h2><div class="shop-admin-actions"><button class="secondary" data-promo="tab" data-tab="automatic" aria-pressed="${section==='automatic'}">Promoções automáticas</button><button class="secondary" data-promo="tab" data-tab="coupons" aria-pressed="${section==='coupons'}">Cupons e origem</button></div></div>${error?`<p role="alert" class="notice">${e(error)}</p>`:''}${busy&&!data?'<p role="status">Carregando regras…</p>':''}${!data?'':`<section class="card"><h3>Como combinar os descontos</h3><form data-promo-form="mode"><label>Regra da loja<select name="mode"><option value="best" ${data.mode==='best'?'selected':''}>Aplicar somente o maior desconto</option><option value="combine" ${data.mode==='combine'?'selected':''}>Acumular as permitidas e comparar com a melhor exclusiva</option></select></label><p class="sub">No acúmulo, as regras são aplicadas da mais antiga à mais nova sobre o saldo dos produtos. A combinação permitida é comparada às exclusivas e vence o menor total para o cliente.</p><button class="secondary space" ${busy?'disabled':''}>Salvar combinação</button></form></section>${draft?editor():`<button class="primary space" data-promo="new" ${busy?'disabled':''}>＋ ${section==='coupons'?'Criar cupom':'Criar promoção'}</button><div class="shop-discount-list space">${rows.map(r=>`<article class="card"><div class="between"><h3>${e(r.name)}</h3><span class="tag">${r.active?'Ativa':'Pausada'}</span></div>${r.code?`<strong class="shop-coupon-code">${e(r.code)}</strong>`:''}<p>${r.kind==='tracking'?'Somente origem':r.kind==='percent'?(r.value/100).toLocaleString('pt-BR')+'% de desconto':money(r.value)+' de desconto'} · ${r.stackable?'Permite acúmulo':'Exclusiva'}</p><p class="sub">A partir de ${r.min_quantity} unidade(s) e ${money(r.min_subtotal_cents)} em produtos participantes. ${r.payment_method==='any'?'Qualquer pagamento':e({pix:'Pix',credit_card:'Cartão de crédito',boleto:'Boleto'}[r.payment_method])}.${r.ends_at?' Até '+e(new Date(r.ends_at).toLocaleString('pt-BR'))+'.':''}</p>${r.source?`<p>Origem: ${e(r.source)}</p>`:''}${r.referrer_email?`<p class="sub">Indicação: ${e(r.referrer_email)}</p>`:''}${r.restricted_email?`<p class="sub">Exclusivo: ${e(r.restricted_email)}</p>`:''}<p class="sub">${r.paid_orders||0} pedidos pagos · ${r.reserved_uses||0} usos reservados${r.code?' · Vendas atribuídas: '+money(r.paid_total_cents||0):''}</p><div class="shop-admin-actions"><button class="secondary" data-promo="edit" data-id="${e(r.id)}">Editar</button><button class="text-btn" data-promo="toggle" data-id="${e(r.id)}">${r.active?'Pausar':'Ativar'}</button></div></article>`).join('')||'<p class="sub">Nenhuma regra cadastrada nesta seção.</p>'}</div>`}`}`;}
 document.addEventListener('click',async event=>{const b=event.target.closest('[data-promo]');if(!b||busy||!ctx.admin)return;const token=revision;error='';if(b.dataset.promo==='tab'){section=b.dataset.tab;draft=null;}else if(b.dataset.promo==='new')draft={kind:'percent',value:1000,active:true,payment_method:'any',min_quantity:1};else if(b.dataset.promo==='cancel')draft=null;else if(b.dataset.promo==='edit')draft={...data.rules.find(r=>r.id===b.dataset.id)};else if(b.dataset.promo==='toggle'){const r=data.rules.find(r=>r.id===b.dataset.id);busy=true;try{await rpc('promotion_toggle',{id:r.id,active:!r.active});const result=await rpc('promotions');if(token===revision)data=result;}catch(err){if(token===revision)error=err.message;}finally{if(token===revision)busy=false;}}if(token===revision)redraw();});
 document.addEventListener('submit',async event=>{const f=event.target;if(!f.matches('[data-promo-form]'))return;event.preventDefault();if(busy||!ctx.admin||!f.reportValidity())return;const values=Object.fromEntries(new FormData(f)),token=revision;busy=true;error='';try{if(f.dataset.promoForm==='mode')await rpc('discount_settings',{mode:values.mode});else {const kind=values.kind,amount=kind==='tracking'?0:window.NeoShopCore.cents(values.amount);if(kind==='percent'&&amount>10000)throw Error('O percentual deve ser maior que zero e até 100%.');const payload={...values,id:draft.id||null,code:section==='coupons'?values.code:'',kind,value:amount,min_quantity:Number(values.min_quantity),min_subtotal_cents:window.NeoShopCore.cents(values.minimum,true),max_discount_cents:values.maximum?window.NeoShopCore.cents(values.maximum):null,product_ids:Array.from(f.querySelectorAll('[name=product_ids]:checked')).map(el=>el.value),active:values.active==='on',stackable:values.stackable==='on',starts_at:values.starts_at?new Date(values.starts_at).toISOString():null,ends_at:values.ends_at?new Date(values.ends_at).toISOString():null,max_uses:values.max_uses?Number(values.max_uses):null,per_user_limit:values.per_user_limit?Number(values.per_user_limit):null};await rpc('promotion_save',payload);}const result=await rpc('promotions');if(token===revision){data=result;draft=null;}}catch(err){if(token===revision)error=err.message;}finally{if(token===revision){busy=false;if(error){const old=document.querySelector('[data-promo-error]');old?.remove();const p=document.createElement('p');p.dataset.promoError='';p.setAttribute('role','alert');p.textContent=error;f.prepend(p);}else redraw();}}});
 return {session,open,view};
})();
